def read(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def summarize(root,board,mode):
 p=root/'full'/f'{board}-{mode}'
 progress=read(p/'progress.json');assessment=read(p/'assessment.json');process=read(p/'process.json');diagnostics=read(p/'diagnostics.json')
