for row in rows:
 a=row['ddr']['before']['assessment'];b=row['ddr']['after']['assessment'];control.append(dict(board=row['id'],metricsIdentical=all(a[k]==b[k] for k in metrics),before={k:a[k] for k in metrics},after={k:b[k] for k in metrics}))
report['ddrEquivalence']=control
(out/'analysis.json').write_text(json.dumps(report,indent=2)+'\n')
(out/'setup-pairs.json').write_text(json.dumps(setup,indent=2)+'\n')
