setuptable=''.join(f"<tr><td>{r['board']}</td><td>{r['beforeMs']/1000:.2f}s</td><td>{r['afterMs']/1000:.2f}s</td><td>{r['reductionPercent']:.1f}%</td><td>Identical</td></tr>" for r in fanout)
